nextflow_process {

    name "Test Process SKESA"
    script "../main.nf"
    process "SKESA"

    tag "modules"
    tag "modules_nfcore"
    tag "skesa"

    test("sarscov2 - fastq - single_end") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/sarscov2_mus-musculus.fastq.gz', checkIfExists: true),
                ]
                """
            }
        }
        then {
            assert process.success
            assertAll(
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - fastq - paired_end") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_germline_1.fq.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_germline_2.fq.gz', checkIfExists: true),]
                ]
                """
            }
        }
        then {
            assert process.success
            assertAll(
                { assert snapshot(process.out).match() }
            )
        }

    }


    test("sarscov2 - fastq - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/sarscov2_mus-musculus.fastq.gz', checkIfExists: true),
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(process.out).match() }
            )
        }
    }
}

